-- Canonical initial schema. Startup uses SQLAlchemy metadata.create_all for this small project.
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY,email VARCHAR(120) UNIQUE NOT NULL,role VARCHAR(20) NOT NULL,password_hash VARCHAR(200) NOT NULL);
CREATE TABLE IF NOT EXISTS students (id SERIAL PRIMARY KEY,code VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(80) NOT NULL,campus VARCHAR(50) NOT NULL,"group" VARCHAR(20) NOT NULL,score FLOAT,absent BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS plans (id SERIAL PRIMARY KEY,title VARCHAR(120) UNIQUE NOT NULL,campus VARCHAR(50) NOT NULL,exclude_absent BOOLEAN NOT NULL,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id SERIAL PRIMARY KEY,plan_id INTEGER NOT NULL REFERENCES plans(id),status VARCHAR(20) NOT NULL,result JSON,error TEXT NOT NULL,conclusion TEXT NOT NULL,published BOOLEAN NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id SERIAL PRIMARY KEY,actor VARCHAR(120) NOT NULL,action VARCHAR(200) NOT NULL,status INTEGER NOT NULL,created_at VARCHAR(40) NOT NULL);
-- 成绩勘误与整批评分 (新增)
CREATE TABLE IF NOT EXISTS exams (id SERIAL PRIMARY KEY,title VARCHAR(120) UNIQUE NOT NULL,max_score FLOAT NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS questions (id SERIAL PRIMARY KEY,exam_id INTEGER NOT NULL REFERENCES exams(id),number VARCHAR(20) NOT NULL,full_score FLOAT NOT NULL,answer VARCHAR(20),cancelled BOOLEAN NOT NULL,CONSTRAINT uq_question_exam_number UNIQUE(exam_id,number));
CREATE TABLE IF NOT EXISTS answer_sheets (id SERIAL PRIMARY KEY,exam_id INTEGER NOT NULL REFERENCES exams(id),student_code VARCHAR(50) NOT NULL,answers JSON NOT NULL,absent BOOLEAN NOT NULL,appeal_score FLOAT,appeal_note TEXT NOT NULL,appeal_version INTEGER NOT NULL,CONSTRAINT uq_sheet_exam_code UNIQUE(exam_id,student_code));
CREATE TABLE IF NOT EXISTS batches (id SERIAL PRIMARY KEY,exam_id INTEGER NOT NULL REFERENCES exams(id),status VARCHAR(20) NOT NULL,version INTEGER NOT NULL,published_version INTEGER,published_checksum VARCHAR(80) NOT NULL DEFAULT '',recalc_checksum VARCHAR(80) NOT NULL DEFAULT '',published_snapshot JSON,created_at VARCHAR(40) NOT NULL,published_at VARCHAR(40),explanation TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS batch_scores (id SERIAL PRIMARY KEY,batch_id INTEGER NOT NULL REFERENCES batches(id),student_code VARCHAR(50) NOT NULL,raw_score FLOAT,percent_score FLOAT,previous_raw FLOAT,previous_percent FLOAT,absent BOOLEAN NOT NULL,contributions JSON NOT NULL DEFAULT '{}',conflict BOOLEAN NOT NULL DEFAULT FALSE,resolved_appeal_version INTEGER NOT NULL DEFAULT 0,resolution_decision VARCHAR(20) NOT NULL DEFAULT '',published_score FLOAT,published_percent FLOAT,published_source VARCHAR(20) NOT NULL DEFAULT '',explanation TEXT NOT NULL DEFAULT '',CONSTRAINT uq_score_batch_code UNIQUE(batch_id,student_code));
CREATE TABLE IF NOT EXISTS reflections (id SERIAL PRIMARY KEY,batch_id INTEGER NOT NULL REFERENCES batches(id),version INTEGER NOT NULL,created_at VARCHAR(40) NOT NULL,rule_version VARCHAR(80) NOT NULL DEFAULT '',removed_full FLOAT NOT NULL DEFAULT 0,remaining_full FLOAT NOT NULL DEFAULT 0,appellated INTEGER NOT NULL DEFAULT 0,conflicts INTEGER NOT NULL DEFAULT 0,summary JSON NOT NULL DEFAULT '{}',published_snapshot JSON,published_at VARCHAR(40));
CREATE TABLE IF NOT EXISTS appeal_events (id SERIAL PRIMARY KEY,exam_id INTEGER NOT NULL REFERENCES exams(id),student_code VARCHAR(50) NOT NULL,version INTEGER NOT NULL,score FLOAT,note TEXT NOT NULL,actor VARCHAR(120) NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS resolutions (id SERIAL PRIMARY KEY,batch_id INTEGER NOT NULL REFERENCES batches(id),student_code VARCHAR(50) NOT NULL,decision VARCHAR(20) NOT NULL,appeal_version INTEGER NOT NULL DEFAULT 0,appeal_score FLOAT,raw_score FLOAT,actor VARCHAR(120) NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS publish_attempts (id SERIAL PRIMARY KEY,batch_id INTEGER NOT NULL REFERENCES batches(id),request_key VARCHAR(80) NOT NULL,status VARCHAR(20) NOT NULL,version INTEGER,created_at VARCHAR(40) NOT NULL,finished_at VARCHAR(40),CONSTRAINT uq_publish_batch_key UNIQUE(batch_id,request_key));
CREATE TABLE IF NOT EXISTS verifications (id SERIAL PRIMARY KEY,batch_id INTEGER NOT NULL REFERENCES batches(id),exam_id INTEGER NOT NULL REFERENCES exams(id),published_version INTEGER NOT NULL,checksum VARCHAR(80) NOT NULL,reflection_id INTEGER,rules JSON NOT NULL DEFAULT '[]',statistics JSON NOT NULL DEFAULT '{}',evidence JSON NOT NULL DEFAULT '{}',created_by VARCHAR(120) NOT NULL DEFAULT '',created_at VARCHAR(40) NOT NULL);
